<?php
declare(strict_types=1);
require_once __DIR__.'/harness.php';require_once __DIR__.'/database.php';require_once __DIR__.'/support-c-fixture.php';
use Hostider\Support\Mail\{Mime,Attachments,Tokens,Commands,DeniedAdapter,TestAdapter,Retention,FileStore,Common,Factory,Inbound};
use Hostider\Core\Http\HttpError;
use Hostider\Core\{Id,CanonicalJson};
function cSimple(): array{return ['client'=>['email'=>'synthetic@example.invalid']];}
test('SUP-001 MIME strict plain text and RFC references preserve bounded canonical values',function(): void{$raw=cRaw(cSimple(),['Message-ID'=>'<one@example.invalid>','References'=>'<parent@example.invalid> <older@example.invalid>','In-Reply-To'=>'<parent@example.invalid>']);$m=Mime::parse($raw);same('<one@example.invalid>',$m['message_id']);same(['<parent@example.invalid>','<older@example.invalid>'],$m['references']);same('synthetic@example.invalid',$m['from']);});
test('SUP-001 duplicate folded injected and oversized headers fail closed',function(): void{foreach([str_replace('To:','from: forged@example.invalid' ."\r\n".'To:',cRaw(cSimple())),str_replace('Subject:',' folded' ."\r\n".'Subject:',cRaw(cSimple())),cRaw(cSimple(),['Subject'=>str_repeat('x',999)]),str_replace("\r\n","\n",cRaw(cSimple()))] as $raw){raises(HttpError::class,fn()=>Mime::parse($raw));}});
test('SUP-001 body raw header-count encoded subject and nested MIME limits reject',function(): void{$extra=[];for($n=0;$n<41;++$n){$extra['X-Test-'.$n]='x';}foreach([cRaw(cSimple(),['BODY'=>str_repeat('x',16001)]),str_repeat('x',131073),cRaw(cSimple(),$extra),cRaw(cSimple(),['Subject'=>'=?UTF-8?B?eA==?=']),cRaw(cSimple(),['Content-Type'=>'multipart/mixed; boundary="nested"','BODY'=>"--nested\r\nContent-Type: multipart/mixed; boundary=\"x\"\r\n\r\nx\r\n--nested--\r\n"])] as $raw){raises(HttpError::class,fn()=>Mime::parse($raw));}});
test('SUP-004 traversal HTML SVG ZIP executable and MIME spoof attachments are rejected',function(): void{foreach([['../x.pdf',Attachments::FIXTURE],['x.svg','<svg/>'],['x.html','<script/>'],['x.pdf','PK' ."\x03\x04".str_repeat('x',100)],['x.pdf',"MZ\0evil"],['x.pdf',"%PDF-1.4\n/JavaScript (evil)\n%%EOF\n"],['x.pdf',str_repeat('x',16385)]] as [$name,$bytes]){raises(HttpError::class,fn()=>Attachments::validate($name,$bytes));}same(1,count(Mime::parse(cMultipart(cSimple()))['files']));});
test('SUP-001 HTML body alternate MIME and unknown transfer encoding are never canonical text',function(): void{foreach([['Content-Type'=>'text/html'],['Content-Type'=>'multipart/alternative; boundary="x"'],['Content-Transfer-Encoding'=>'quoted-printable']] as $h){raises(HttpError::class,fn()=>Mime::parse(cRaw(cSimple(),$h)));}});
test('SUP-001 live SMTP and IMAP adapter gates deny before any network operation',function(): void{$a=new DeniedAdapter();same(503,raises(HttpError::class,fn()=>$a->receive())->status);same(503,raises(HttpError::class,fn()=>$a->send())->status);raises(InvalidArgumentException::class,fn()=>new TestAdapter(array_fill(0,26,[])));});

test('SUP-001 unknown sender enters encrypted review without private ticket association',function(): void{$f=cFixture();$t=bTicket($f);$raw=cRaw($f,['From'=>'unknown@example.invalid','Subject'=>'Re: '.$t['number']]);$r=cIn($f,$raw,false);same('REVIEW',$r['status']);same(null,$r['ticket_id']);same(1,(int)$f['db']->execute('SELECT COUNT(*) FROM support_messages')->fetchColumn());$cipher=$f['db']->execute('SELECT raw_encrypted FROM support_mail_inbound WHERE id=?',[$r['id']])->fetchColumn();same(false,str_contains($cipher,'unknown@example.invalid'));same(false,str_contains($cipher,'Synthetic public'));});
test('SUP-002 verified new mail creates exactly one canonical customer message and SLA cycle',function(): void{$f=cFixture(true);$raw=cRaw($f);$r=cIn($f,$raw);same('ATTACHED',$r['status']);same(1,(int)$f['db']->execute('SELECT COUNT(*) FROM support_messages')->fetchColumn());same('customer_reply',$f['db']->execute('SELECT type FROM support_messages WHERE id=?',[$r['message_id']])->fetchColumn());same('TEST_ADAPTER',$f['db']->execute('SELECT origin FROM support_mail_sources WHERE inbound_id=?',[$r['id']])->fetchColumn());same(2,(int)$f['db']->execute('SELECT COUNT(*) FROM support_sla_clocks')->fetchColumn());$before=cCounts($f);same($r,cIn($f,$raw));same($before,cCounts($f));});
test('SUP-002 missing Message-ID dedupes by bounded digest and never auto attaches',function(): void{$f=cFixture();$raw=cRaw($f,['Message-ID'=>null]);$one=cIn($f,$raw);same('MISSING_MESSAGE_ID',$one['reason']);same($one,cIn($f,$raw));same(0,(int)$f['db']->execute('SELECT COUNT(*) FROM support_messages')->fetchColumn());});
test('SUP-002 same Message-ID different bytes becomes immutable conflict review not a second reply',function(): void{$f=cFixture();$id='<same@example.invalid>';$a=cIn($f,cRaw($f,['Message-ID'=>$id]));same('ATTACHED',$a['status']);$b=cIn($f,cRaw($f,['Message-ID'=>$id,'BODY'=>'Different body']));same('MESSAGE_ID_CONFLICT',$b['reason']);same(null,$b['ticket_id']);same(1,(int)$f['db']->execute('SELECT COUNT(*) FROM support_messages')->fetchColumn());for($n=0;$n<2;++$n){cIn($f,cRaw($f,['Message-ID'=>$id,'BODY'=>'Variant'.$n]));}same(413,raises(HttpError::class,fn()=>cIn($f,cRaw($f,['Message-ID'=>$id,'BODY'=>'Too many'])))->status);same(4,(int)$f['db']->execute('SELECT COUNT(*) FROM support_mail_inbound')->fetchColumn());raises(PDOException::class,fn()=>$f['db']->execute('UPDATE support_mail_claims SET raw_sha=raw_sha'));});
test('SUP-001 forged subject and wrong raw or foreign customer sender evidence cannot attach',function(): void{$f=cFixture();$t=bTicket($f);$raw=cRaw($f,['Subject'=>'Re: '.$t['number']]);$r=cIn($f,$raw);same('REVIEW',$r['status']);same(null,$r['ticket_id']);$raw=cRaw($f);$wrong=cProof($f,cRaw($f));same('REVIEW',$f['inbound']->ingest($f['departments'][0],$raw,$wrong)['status']);same('REVIEW',$f['inbound']->ingest($f['departments'][0],cRaw($f),cProof($f,cRaw($f),$f['other']))['status']);same(1,(int)$f['db']->execute('SELECT COUNT(*) FROM support_messages')->fetchColumn());});
test('SUP-001 verified own scoped reply requires token reference ownership and drives NEXT clock',function(): void{$f=cFixture(true);$t=bTicket($f);bReply($f,$t);cDrain($f);$r=cIn($f,cReplyRaw($f,$t));same('ATTACHED',$r['status']);same($t['id'],$r['ticket_id']);same(1,(int)$f['db']->execute("SELECT COUNT(*) FROM support_sla_clocks WHERE metric='NEXT'")->fetchColumn());same('COMPLETED',array_values(array_filter(bClocks($f,$t),fn($c)=>$c['metric']==='FIRST'))[0]['status']);});
test('SUP-001 forged expired and revoked-session reply tokens fail despite fresh sender evidence',function(): void{$f=cFixture();$t=bTicket($f);bReply($f,$t);cDrain($f);$token=(new Tokens($f['mail']))->reply($f['client']['reference'],$t['id']);$raw=cReplyRaw($f,$t,substr($token,0,-1).($token[-1]==='a'?'b':'a'));same('REVIEW',cIn($f,$raw)['status']);$expired=$f['db']->transaction(fn()=>$f['c']->identity->locked($f['client']['reference'],'client',fn($u,$s)=>(new Tokens($f['mail']))->issue('REPLY',$u,$s,$f['departments'][0],$t['id'],ttl:1)));sleep(2);same('REVIEW',cIn($f,cReplyRaw($f,$t,$expired))['status']);$f['db']->execute("UPDATE identity_sessions SET revoked_at=UTC_TIMESTAMP(6) WHERE native_reference=? AND context='client'",[$f['client']['reference']]);$f['client']['reference']=Id::uuid();$f['c']->identity->login($f['client']['email'],$f['client']['password'],'client',$f['client']['reference'],Id::uuid());same('REVIEW',cIn($f,cReplyRaw($f,$t,$token))['status']);same(2,(int)$f['db']->execute('SELECT COUNT(*) FROM support_messages')->fetchColumn());});
test('SUP-001 mixed references or foreign ticket token never cross customer ownership',function(): void{$f=cFixture();$t=bTicket($f);bReply($f,$t);cDrain($f);$other=bTicket($f,who:$f['other']);$raw=cReplyRaw($f,$t);$raw=str_replace('References: '.cDelivery($f,$t)['message_ref'],'References: <forged@example.invalid>',$raw);same('REVIEW',cIn($f,$raw)['status']);same(404,raises(HttpError::class,fn()=>(new Tokens($f['mail']))->reply($f['other']['reference'],$t['id']))->status);same($f['other']['customer'],bRow($f,$other)['customer_id']);same(3,(int)$f['db']->execute('SELECT COUNT(*) FROM support_messages')->fetchColumn());});
test('SUP-003 internal note emits no mail delivery template attachment or customer outbound',function(): void{$f=cFixture();$t=bTicket($f);$before=cCounts($f);$note=bReply($f,$t,'note');same($before['support_mail_outbound'],cCounts($f)['support_mail_outbound']);same($before['outbox_events'],cCounts($f)['outbox_events']);same(404,raises(HttpError::class,fn()=>$f['files']->upload($f['admin']['reference'],'admin',['ticket_id'=>$t['id'],'message_id'=>$note['message_id'],'version'=>(int)bRow($f,$t)['version'],'name'=>'note.pdf','base64'=>base64_encode(Attachments::FIXTURE)],Id::uuid(),Id::uuid()))->status);same(0,cCounts($f)['support_mail_files']);});
test('SUP-001 bounce autoresponder precedence and loop markers are blocked even with valid proof',function(): void{$f=cFixture();foreach([['Auto-Submitted'=>'auto-replied'],['Return-Path'=>'<>'],['Precedence'=>'bulk'],['X-Hostider-Loop'=>'1'],['Content-Type'=>'multipart/report']] as $h){$r=cIn($f,cRaw($f,$h));same('BLOCKED',$r['status']);same('MAIL_LOOP',$r['reason']);}same(0,cCounts($f)['support_messages']);});
test('SUP-001 malformed MIME is encrypted bounded review and oversized raw writes nothing',function(): void{$f=cFixture();$r=cIn($f,cRaw($f,['Content-Type'=>'text/html']),false);same('MALFORMED_MIME',$r['reason']);$before=cCounts($f);same(413,raises(HttpError::class,fn()=>$f['inbound']->ingest($f['departments'][0],str_repeat('x',131073)))->status);same($before,cCounts($f));});
test('SUP-004 inbound files default quarantine and exact fixture is only TEST_CLEAN not real AV',function(): void{$f=cFixture();$r=cIn($f,cMultipart($f,'inert.pdf',"%PDF-1.4\n% other inert fixture\n%%EOF\n"));same('ATTACHED',$r['status']);$file=$f['db']->execute('SELECT * FROM support_mail_files WHERE message_id=?',[$r['message_id']])->fetch();same('QUARANTINED',$file['scan_status']);same(423,raises(HttpError::class,fn()=>$f['files']->token($f['client']['reference'],'client',$file['id']))->status);$r=cIn($f,cMultipart($f));$file=$f['db']->execute('SELECT * FROM support_mail_files WHERE message_id=?',[$r['message_id']])->fetch();same('TEST_CLEAN',$file['scan_status']);same(hash('sha256',Attachments::FIXTURE),$file['sha256']);});
test('SUP-004 native HTTP upload download headers foreign customer and CSRF isolation',function(): void{$f=cFixture();$t=bTicket($f);$s=new HttpTestServer(dirname(__DIR__),bEnvironment($f),__DIR__.'/commerce-router.php');$auth=['cookies'=>[],'csrf'=>''];$other=$auth;try{paClientC($s,$f['client'],$auth);$p=['ticket_id'=>$t['id'],'message_id'=>$t['message_id'],'version'=>1,'name'=>'fixture.pdf','base64'=>base64_encode(Attachments::FIXTURE)];same(403,bHttp($s,'/api/v1/client/support-mail/upload',$auth,$p,csrf:false)[0]);$r=bHttp($s,'/api/v1/client/support-mail/upload',$auth,$p);same(200,$r[0]);$id=$r[1]['data']['id'];$token=bHttp($s,'/api/v1/client/support-mail/download-token',$auth,['id'=>$id]);same(200,$token[0]);$options=[CURLOPT_HTTPHEADER=>['X-Download-Token: '.$token[1]['data']['token']],CURLOPT_COOKIE=>implode('; ',array_map(fn($k,$v)=>$k.'='.$v,array_keys($auth['cookies']),$auth['cookies']))];[$status,$bytes,$headers]=$s->request('/api/v1/client/support-mail/download?id='.$id,$options);same(200,$status);same(Attachments::FIXTURE,$bytes);same(true,str_contains(strtolower(implode("\n",$headers)),'cache-control: no-store'));same(true,str_contains(strtolower(implode("\n",$headers)),'content-disposition: attachment;'));paClientC($s,$f['other'],$other);same(404,bHttp($s,'/api/v1/client/support-mail/download-token',$other,['id'=>$id])[0]);same(404,bHttp($s,'/api/v1/client/support-mail/upload',$other,$p)[0]);}finally{$s->stop();}});
function paClientC(HttpTestServer $s,array $who,array &$a): void{bHttp($s,'/api/v1/client/identity/bootstrap',$a);same(200,bHttp($s,'/api/v1/client/identity/login',$a,['email'=>$who['email'],'password'=>$who['password']])[0]);}
test('SUP-004 file integrity wrong token and session revocation deny download',function(): void{$f=cFixture();$r=cIn($f,cMultipart($f));$id=$f['db']->execute('SELECT id FROM support_mail_files WHERE message_id=?',[$r['message_id']])->fetchColumn();$token=$f['files']->token($f['client']['reference'],'client',$id)['token'];raises(HttpError::class,fn()=>$f['files']->download($f['other']['reference'],'client',$id,$token,Id::uuid()));$f['db']->execute("UPDATE identity_sessions SET revoked_at=UTC_TIMESTAMP(6) WHERE native_reference=?",[$f['client']['reference']]);same(401,raises(HttpError::class,fn()=>$f['files']->download($f['client']['reference'],'client',$id,$token,Id::uuid()))->status);raises(PDOException::class,fn()=>$f['db']->execute('UPDATE support_mail_files SET sha256=? WHERE id=?',[str_repeat('0',64),$id]));});
test('SUP-001 native HTTP review requires fresh MFA wildcard scope and no private list metadata',function(): void{$f=cFixture();$r=cIn($f,cRaw($f,['From'=>'unknown@example.invalid']),false);$s=new HttpTestServer(dirname(__DIR__),bEnvironment($f),__DIR__.'/commerce-router.php');$a=['cookies'=>[],'csrf'=>''];try{same(401,bHttp($s,'/api/v1/admin/support-mail/list?department_id='.$f['departments'][0],$a)[0]);bLogin($s,$f['admin'],$a);$list=bHttp($s,'/api/v1/admin/support-mail/list?department_id='.$f['departments'][0],$a);same(200,$list[0]);same([$r['id']],array_column($list[1]['data'],'id'));foreach(['subject','body','raw_encrypted','ticket_id','customer_id','unknown@example.invalid'] as $hidden){same(false,str_contains($list[2],$hidden));}$raw=bHttp($s,'/api/v1/admin/support-mail/raw?id='.$r['id'],$a);same(200,$raw[0]);$result=cPost($s,'execute',$a,'review',['id'=>$r['id'],'version'=>1,'decision'=>'reject','proof'=>'']);same(200,$result[0]);same('REJECTED',$result[1]['data']['status']);$f['db']->execute('DELETE FROM support_department_members WHERE department_id=? AND user_id=?',[$f['departments'][0],$f['admin']['user']]);same(404,bHttp($s,'/api/v1/admin/support-mail/raw?id='.$r['id'],$a)[0]);}finally{$s->stop();}});
test('SUP-001 review approval revalidates sender proof and never force-maps unknown address',function(): void{$f=cFixture();$raw=cRaw($f);$r=cIn($f,$raw,false);$proof=cProof($f,$raw);$out=cCommand($f,'review',['id'=>$r['id'],'version'=>1,'decision'=>'approve','proof'=>$proof]);same('ATTACHED',$out['status']);same(1,cCounts($f)['support_messages']);$badRaw=cRaw($f,['From'=>'unverified@example.invalid']);$bad=cIn($f,$badRaw,false);same(403,raises(HttpError::class,fn()=>cCommand($f,'review',['id'=>$bad['id'],'version'=>1,'decision'=>'approve','proof'=>cProof($f,$badRaw)]))->status);same(1,cCounts($f)['support_messages']);});
test('SUP-002 inbound 1 4 8 independent PHP workers produce one message per raw Message-ID',function(): void{$f=cFixture();foreach([1,4,8] as $workers){$raw=cRaw($f);$before=cCounts($f)['support_messages'];$r=cRace($f,['op'=>'inbound','department_id'=>$f['departments'][0],'raw_base64'=>base64_encode($raw),'proof'=>cProof($f,$raw)],$workers);$ids=array_column(array_column($r,'result'),'message_id');same(1,count(array_unique($ids)));same($before+1,cCounts($f)['support_messages']);}same(3,cCounts($f)['support_mail_sources']);});
test('SUP-002 outbound 1 4 8 independent workers accept a public delivery once without DELIVERED',function(): void{$f=cFixture();foreach([1,4,8] as $workers){$t=bTicket($f);bReply($f,$t);cDrain($f);$d=cDelivery($f,$t);$req=cCommand($f,'dispatch',['id'=>$d['id'],'version'=>(int)$d['version'],'mode'=>'ACCEPTED_BY_TRANSPORT']);$q=new \Hostider\Core\Queue\Queue($f['db']);$o=new \Hostider\Core\Queue\Outbox($f['db'],$q);while($o->dispatchOne()){}$p=['event_uuid'=>$req['event_uuid'],'delivery_id'=>$d['id']];$r=cRace($f,['op'=>'dispatch','payload'=>$p],$workers);same(array_fill(0,$workers,'SUCCEEDED'),array_column($r,'result'));same(1,(int)$f['db']->execute('SELECT COUNT(*) FROM support_mail_transport WHERE delivery_id=?',[$d['id']])->fetchColumn());same(1,(int)$f['db']->execute('SELECT COUNT(*) FROM support_mail_attempts WHERE delivery_id=?',[$d['id']])->fetchColumn());same('ACCEPTED_BY_TRANSPORT',cDelivery($f,$t)['status']);same('SUCCEEDED',$f['outbound']->dispatch($p));}same(0,(int)$f['db']->execute("SELECT COUNT(*) FROM support_mail_outbound WHERE status='DELIVERED'")->fetchColumn());});
test('SUP-002 outbound retryable and permanent mock outcomes require explicit bounded retry',function(): void{$f=cFixture();$t=bTicket($f);bReply($f,$t);cDrain($f);$d=cDelivery($f,$t);cCommand($f,'dispatch',['id'=>$d['id'],'version'=>(int)$d['version'],'mode'=>'RETRYABLE_FAILURE']);cDrain($f);same('RETRYABLE_FAILURE',cDelivery($f,$t)['status']);same(0,cCounts($f)['support_mail_transport']);$d=cDelivery($f,$t);cCommand($f,'dispatch',['id'=>$d['id'],'version'=>(int)$d['version'],'mode'=>'PERMANENT_FAILURE']);cDrain($f);same('PERMANENT_FAILURE',cDelivery($f,$t)['status']);$d=cDelivery($f,$t);same(409,raises(HttpError::class,fn()=>cCommand($f,'dispatch',['id'=>$d['id'],'version'=>(int)$d['version'],'mode'=>'ACCEPTED_BY_TRANSPORT']))->status);same(0,cCounts($f)['support_mail_transport']);});
test('SUP-002 unpublished forged extra payload and fingerprint mismatch never mint mail receipts',function(): void{$f=cFixture();$t=bTicket($f);bReply($f,$t);$d=cDelivery($f,$t);$e=$f['db']->execute('SELECT payload FROM outbox_events WHERE event_uuid=?',[$d['event_id']])->fetchColumn();$p=json_decode($e,true,32,JSON_THROW_ON_ERROR);same('FAILED',$f['outbound']->ready($p));cDrain($f);same('FAILED',$f['outbound']->ready($p+['extra'=>true]));same('FAILED',$f['outbound']->ready(array_replace($p,['customer_id'=>$f['other']['customer']])));$f['db']->execute('UPDATE jobs SET payload_fingerprint=? WHERE dedupe_key=?',[str_repeat('0',64),'outbox:'.$p['event_uuid']]);same('FAILED',$f['outbound']->ready($p));same(1,(int)$f['db']->execute("SELECT COUNT(*) FROM inbox_events WHERE consumer='support.mail.held.v1' AND event_uuid=?",[$p['event_uuid']])->fetchColumn());});
test('SUP-004 quarantined attachment prevents mock transport acceptance',function(): void{$f=cFixture();$t=bTicket($f);$reply=bReply($f,$t);$f['files']->upload($f['admin']['reference'],'admin',['ticket_id'=>$t['id'],'message_id'=>$reply['message_id'],'version'=>(int)bRow($f,$t)['version'],'name'=>'unsafe.pdf','base64'=>base64_encode("%PDF-1.4\n% unscanned\n%%EOF\n")],Id::uuid(),Id::uuid());cDrain($f);$d=cDelivery($f,$t);cCommand($f,'dispatch',['id'=>$d['id'],'version'=>(int)$d['version'],'mode'=>'ACCEPTED_BY_TRANSPORT']);cDrain($f);same('HELD',cDelivery($f,$t)['status']);same(0,cCounts($f)['support_mail_transport']);});
test('SUP-002 database failure rolls back inbound canonical message outbox and source receipt',function(): void{$f=cFixture();$raw=cMultipart($f);$proof=cProof($f,$raw);$before=cCounts($f);$f['db']->execute("CREATE TRIGGER c_fail_source BEFORE INSERT ON support_mail_sources FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic mail rollback'");try{raises(PDOException::class,fn()=>$f['inbound']->ingest($f['departments'][0],$raw,$proof));same($before,cCounts($f));}finally{$f['db']->execute('DROP TRIGGER c_fail_source');}});
