test('SUP-004 retention hold preserves evidence and purge keeps immutable metadata',function(): void{$f=cFixture();$r=cIn($f,cMultipart($f));$file=$f['db']->execute('SELECT * FROM support_mail_files WHERE message_id=?',[$r['message_id']])->fetch();$f['db']->execute('UPDATE support_mail_files SET expires_at=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 1 DAY) WHERE id=?',[$file['id']]);$f['db']->execute('UPDATE support_mail_inbound SET expires_at=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 1 DAY) WHERE id=?',[$r['id']]);cCommand($f,'hold',['id'=>$file['id'],'version'=>1,'kind'=>'FILE','hold'=>true]);$ret=new Retention($f['mail'],$f['files']->store);$ret->run();same(null,$f['db']->execute('SELECT purged_at FROM support_mail_files WHERE id=?',[$file['id']])->fetchColumn());same(null,$f['db']->execute('SELECT raw_encrypted FROM support_mail_inbound WHERE id=?',[$r['id']])->fetchColumn());cCommand($f,'hold',['id'=>$file['id'],'version'=>2,'kind'=>'FILE','hold'=>false]);$ret->run();same(1,(int)$f['db']->execute('SELECT physical_removed FROM support_mail_files WHERE id=?',[$file['id']])->fetchColumn());same($file['sha256'],$f['db']->execute('SELECT sha256 FROM support_mail_files WHERE id=?',[$file['id']])->fetchColumn());same(404,raises(HttpError::class,fn()=>$f['files']->token($f['client']['reference'],'client',$file['id']))->status);raises(PDOException::class,fn()=>$f['db']->execute('DELETE FROM support_mail_sources'));});
test('SUP-001 native HTTP sender proof and adapter ingestion use current scoped session atomically',function(): void{$f=cFixture(true);$s=new HttpTestServer(dirname(__DIR__),bEnvironment($f),__DIR__.'/commerce-router.php');$client=['cookies'=>[],'csrf'=>''];$admin=$client;try{paClientC($s,$f['client'],$client);bLogin($s,$f['admin'],$admin);$raw=cRaw($f);$proof=bHttp($s,'/api/v1/client/support-mail/proof',$client,['department_id'=>$f['departments'][0],'sha256'=>hash('sha256',$raw)]);same(200,$proof[0]);$p=['department_id'=>$f['departments'][0],'raw_base64'=>base64_encode($raw),'proof'=>$proof[1]['data']['proof']];same(403,bHttp($s,'/api/v1/admin/support-mail/ingest',$admin,$p,csrf:false)[0]);$r=bHttp($s,'/api/v1/admin/support-mail/ingest',$admin,$p);same(200,$r[0]);same('ATTACHED',$r[1]['data']['status']);same(false,isset($r[1]['data']['ticket_id']));same(1,cCounts($f)['support_messages']);same(2,cCounts($f)['support_sla_clocks']);$before=cCounts($f);same($r[1]['data'],bHttp($s,'/api/v1/admin/support-mail/ingest',$admin,$p)[1]['data']);same($before,cCounts($f));$f['db']->execute("UPDATE identity_sessions SET verified_at=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 10 MINUTE) WHERE user_id=? AND context='admin'",[$f['admin']['user']]);same(403,bHttp($s,'/api/v1/admin/support-mail/ingest',$admin,$p)[0]);}finally{$s->stop();}});
test('SUP-001 review confirmation payload actor stale version and idempotent replay are enforced',function(): void{$f=cFixture();$raw=cRaw($f);$r=cIn($f,$raw,false);$cmd=new Commands($f['mail']);$body=['action'=>'review','payload'=>['id'=>$r['id'],'version'=>1,'decision'=>'approve','proof'=>cProof($f,$raw)]];$prep=$cmd->command($f['admin']['reference'],'prepare',$body,Id::uuid(),Id::uuid());$body['confirmation']=['id'=>$prep['id'],'accepted'=>true];$key=Id::uuid();$one=$cmd->command($f['admin']['reference'],'execute',$body,$key,Id::uuid());$before=cCounts($f);same($one,$cmd->command($f['admin']['reference'],'execute',$body,$key,Id::uuid()));same($before,cCounts($f));same(409,raises(HttpError::class,fn()=>$cmd->command($f['admin']['reference'],'execute',$body,Id::uuid(),Id::uuid()))->status);$body['payload']['decision']='reject';same(409,raises(HttpError::class,fn()=>$cmd->command($f['admin']['reference'],'execute',$body,$key,Id::uuid()))->status);});
test('SUP-004 native staff department and permission revocation invalidate download and review',function(): void{$f=cFixture();$r=cIn($f,cMultipart($f));$id=$f['db']->execute('SELECT id FROM support_mail_files WHERE message_id=?',[$r['message_id']])->fetchColumn();$token=$f['files']->token($f['admin']['reference'],'admin',$id)['token'];$dep=$f['db']->execute('SELECT version FROM support_departments WHERE id=?',[$f['departments'][0]])->fetchColumn();$f['service']->command($f['admin']['reference'],'admin','member',['department_id'=>$f['departments'][0],'user_id'=>$f['admin']['user'],'enabled'=>false,'version'=>(int)$dep],Id::uuid(),Id::uuid());same(404,raises(HttpError::class,fn()=>$f['files']->download($f['admin']['reference'],'admin',$id,$token,Id::uuid()))->status);same(404,raises(HttpError::class,fn()=>(new Commands($f['mail']))->view($f['admin']['reference'],'raw',['id'=>$r['id']],Id::uuid()))->status);});
test('SUP-002 native outbound transaction failure cannot leave false transport acceptance receipt',function(): void{$f=cFixture();$t=bTicket($f);bReply($f,$t);cDrain($f);$d=cDelivery($f,$t);$req=cCommand($f,'dispatch',['id'=>$d['id'],'version'=>(int)$d['version'],'mode'=>'ACCEPTED_BY_TRANSPORT']);$o=new \Hostider\Core\Queue\Outbox($f['db'],new \Hostider\Core\Queue\Queue($f['db']));while($o->dispatchOne()){}$p=['event_uuid'=>$req['event_uuid'],'delivery_id'=>$d['id']];$before=cCounts($f);$f['db']->execute("CREATE TRIGGER c_attempt_failure BEFORE INSERT ON support_mail_attempts FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic dispatch rollback'");try{raises(PDOException::class,fn()=>$f['outbound']->dispatch($p));same($before,cCounts($f));same(0,(int)$f['db']->execute("SELECT COUNT(*) FROM inbox_events WHERE consumer='support.mail.mock.v1' AND event_uuid=?",[$p['event_uuid']])->fetchColumn());}finally{$f['db']->execute('DROP TRIGGER c_attempt_failure');}same('SUCCEEDED',$f['outbound']->dispatch($p));same(1,cCounts($f)['support_mail_transport']);});
test('SUP-004 missing or tampered storage prevents both download and mock acceptance',function(): void{$f=cFixture();$t=bTicket($f);$reply=bReply($f,$t);$up=$f['files']->upload($f['admin']['reference'],'admin',['ticket_id'=>$t['id'],'message_id'=>$reply['message_id'],'version'=>(int)bRow($f,$t)['version'],'name'=>'fixture.pdf','base64'=>base64_encode(Attachments::FIXTURE)],Id::uuid(),Id::uuid());$id=$up['id'];$token=$f['files']->token($f['client']['reference'],'client',$id)['token'];$f['files']->store->remove($id);raises(HttpError::class,fn()=>$f['files']->download($f['client']['reference'],'client',$id,$token,Id::uuid()));cDrain($f);$d=cDelivery($f,$t);$req=cCommand($f,'dispatch',['id'=>$d['id'],'version'=>(int)$d['version'],'mode'=>'ACCEPTED_BY_TRANSPORT']);$o=new \Hostider\Core\Queue\Outbox($f['db'],new \Hostider\Core\Queue\Queue($f['db']));while($o->dispatchOne()){}raises(HttpError::class,fn()=>$f['outbound']->dispatch(['event_uuid'=>$req['event_uuid'],'delivery_id'=>$d['id']]));same(0,cCounts($f)['support_mail_transport']);});
test('SUP-002 live flag or staging environment cannot activate adapter or mail pipeline',function(): void{$f=cFixture();foreach([['staging',false],['production',true]] as [$env,$mail]){$c=$f['config'];$cfg=new \Hostider\Core\Config($env,$c->url,$c->key,$c->dsn,$c->dbUser,$c->dbPassword,mail:$mail);$m=new Common(new \Hostider\Commerce\Services($f['db'],$cfg));same(503,raises(HttpError::class,fn()=>$m->gate())->status);}});
test('F5-C additive 051 to 052 upgrade protects all old migration checksums and replay',function(): void{$root=dirname(__DIR__);$db=isolatedDomainDb();$dir=$root.'/storage/f5-c-prefix-'.bin2hex(random_bytes(5));mkdir($dir,0700);$files=[];try{foreach(glob($root.'/migrations/*.php') as $p){if(basename($p)<'052'){$to=$dir.'/'.basename($p);copy($p,$to);$files[]=$to;}}same(51,count((new \Hostider\Core\Database\Migrator($db,$dir))->migrate()));$old=$db->execute('SELECT version,checksum,status FROM schema_migrations ORDER BY version')->fetchAll();$m=new \Hostider\Core\Database\Migrator($db,$root.'/migrations');same(['052_support_mail.php'],$m->migrate());same([],$m->migrate());$m->assertReady();same($old,$db->execute("SELECT version,checksum,status FROM schema_migrations WHERE version<'052' ORDER BY version")->fetchAll());}finally{foreach($files as $p){unlink($p);}rmdir($dir);}});
test('SUP-004 public file listing excludes private notes and stale department tokens after move',function(): void{$f=cFixture();$r=cIn($f,cMultipart($f));$t=bRow($f,['id'=>$r['ticket_id']]);$file=$f['db']->execute('SELECT id FROM support_mail_files WHERE message_id=?',[$r['message_id']])->fetchColumn();same(1,count($f['files']->listing($f['client']['reference'],'client',$t['id'],$r['message_id'])));$note=bReply($f,$t,'note');same(404,raises(HttpError::class,fn()=>$f['files']->listing($f['admin']['reference'],'admin',$t['id'],$note['message_id']))->status);$token=$f['files']->token($f['client']['reference'],'client',$file)['token'];supportGrant($f,$f['departments'][1]);$f['service']->command($f['admin']['reference'],'admin','move',['id'=>$t['id'],'version'=>(int)bRow($f,$t)['version'],'department_id'=>$f['departments'][1]],Id::uuid(),Id::uuid());same(403,raises(HttpError::class,fn()=>$f['files']->download($f['client']['reference'],'client',$file,$token,Id::uuid()))->status);$fresh=$f['files']->token($f['client']['reference'],'client',$file)['token'];same(Attachments::FIXTURE,$f['files']->download($f['client']['reference'],'client',$file,$fresh,Id::uuid())['bytes']);});
test('SUP-001 native mail settings are explicit administrative config and mail origin stays visible',function(): void{$f=cFixture();$r=cIn($f,cRaw($f));$detail=$f['service']->view($f['client']['reference'],'client','detail',['id'=>$r['ticket_id']]);same('TEST_ADAPTER',$detail['mail_origin']);same('TEST_ADAPTER',$detail['messages'][0]['mail_origin']);$view=(new Commands($f['mail']))->view($f['admin']['reference'],'settings',['department_id'=>$f['departments'][0]],Id::uuid());same(7,(int)$view['raw_days']);same(1,(int)$view['enabled']);});
test('SUP-002 native CLI stdin test adapter ingests without credentials or network arguments',function(): void{$f=cFixture();$raw=cRaw($f);$p=['department_id'=>$f['departments'][0],'raw_base64'=>base64_encode($raw),'proof'=>cProof($f,$raw)];$pipes=[];$proc=proc_open([PHP_BINARY,dirname(__DIR__).'/bin/console.php','support:mail-ingest'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,null,bEnvironment($f));if(!is_resource($proc)){throw new RuntimeException('CLI unavailable');}fwrite($pipes[0],json_encode($p,JSON_THROW_ON_ERROR));fclose($pipes[0]);$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);same(0,proc_close($proc));same('',$err);same('ATTACHED',json_decode($out,true,32,JSON_THROW_ON_ERROR)[0]['status']);same(1,cCounts($f)['support_messages']);});
test('SUP-002 adapter acknowledgement waits for DB commit and retains failed input',function(): void{$f=cFixture();$raw=cRaw($f);$a=new TestAdapter([['department_id'=>$f['departments'][0],'raw'=>$raw,'proof'=>cProof($f,$raw)]]);$f['db']->execute("CREATE TRIGGER c_ack_failure BEFORE INSERT ON support_mail_sources FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic ack rollback'");try{raises(PDOException::class,fn()=>$f['inbound']->poll($a));same($raw,$a->receive()['raw']);same(0,cCounts($f)['support_messages']);}finally{$f['db']->execute('DROP TRIGGER c_ack_failure');}same('ATTACHED',$f['inbound']->poll($a)[0]['status']);same(null,$a->receive());});
test('SUP-002 adapter ack loss after commit replays immutable Message-ID without duplicate',function(): void{$f=cFixture();$raw=cRaw($f);$e=['department_id'=>$f['departments'][0],'raw'=>$raw,'proof'=>cProof($f,$raw)];$a=new class($e) implements \Hostider\Support\Mail\InboundAdapter{private bool $fail=true;public function __construct(private ?array $e){}public function receive(): ?array{return $this->e;}public function acknowledge(): void{if($this->fail){$this->fail=false;throw new RuntimeException('Synthetic ack loss');}$this->e=null;}};raises(RuntimeException::class,fn()=>$f['inbound']->poll($a));same(1,cCounts($f)['support_messages']);same('ATTACHED',$f['inbound']->poll($a)[0]['status']);same(1,cCounts($f)['support_messages']);same(null,$a->receive());});
